import ApiService from '../services/api';
import { hasCompletedWorkflowPlanner } from './workflowCompletion';
import { isPartnerPortalSession } from './partnerPortalSession';
import { isAdminPortalUser, getCurrentUserRole } from './authRole';

/** Role-aware destination after a successful unified login. */
export const POST_LOGIN_ROUTES: Record<string, string> = {
  admin: '/admin/dashboard',
  view: '/admin/dashboard',
  partner: '/partner/dashboard',
};

export async function resolveMsmePostLoginDestination(): Promise<string> {
  try {
    const profileResponse = await ApiService.getMSMEProfile();
    const profileData = profileResponse?.data;
    const workflow = profileData?.business?.manufacturingWorkflow;
    const workflowCompleted = hasCompletedWorkflowPlanner(workflow);

    if (!profileData?.companyName) {
      return '/msme-registration';
    }

    if (!workflowCompleted) {
      return '/operations';
    }
  } catch (profileError: unknown) {
    const message = profileError instanceof Error ? profileError.message : '';
    if (message.toLowerCase().includes('not found')) {
      return '/msme-registration';
    }
  }

  return '/dashboard';
}

/** Where to send an already-authenticated user who opens /login. */
export function resolveAuthenticatedHomePath(): string {
  if (isAdminPortalUser()) {
    return '/admin/dashboard';
  }

  if (isPartnerPortalSession() || getCurrentUserRole() === 'partner') {
    return '/partner/dashboard';
  }

  return '/dashboard';
}
