import React from 'react';
import {
  Alert,
  Box,
  Button,
  Container,
  Link,
  Paper,
  Stack,
  Typography,
} from '@mui/material';
import { Link as RouterLink } from 'react-router-dom';
import { PARTNER_CONTACT_EMAIL, PARTNER_PROGRAM_SUMMARY } from '../../constants/partnerProgram';

const PartnersPage: React.FC = () => {
  return (
    <Box sx={{ minHeight: '100vh', bgcolor: 'background.default', py: 4 }}>
      <Container maxWidth="lg">
        <Stack spacing={3}>
          <Box>
            <Typography variant="h4" component="h1" gutterBottom>
              Partners
            </Typography>
            <Typography variant="body1" color="text.secondary" sx={{ maxWidth: 800 }}>
              {PARTNER_PROGRAM_SUMMARY}
            </Typography>
          </Box>

          <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap>
            <Button variant="contained" component={RouterLink} to="/login">
              Partner portal sign in
            </Button>
            <Button variant="outlined" component={RouterLink} to="/register?type=partner">
              Register as partner
            </Button>
          </Stack>

          <Paper sx={{ p: 3 }}>
            <Typography variant="h5" gutterBottom>
              Partner with us
            </Typography>
            <Typography variant="body1" color="text.secondary" paragraph>
              Banks, auditors, verification agencies, and technology integrators can license Carbon
              Intelligence to onboard MSME cohorts, run green-finance workflows, and connect via scoped
              REST APIs. Commercial terms, API scopes, and integration support are tailored to your
              programme.
            </Typography>
            <Typography variant="body1" color="text.secondary">
              To discuss partnership, API access, or custom commercial terms, contact us at{' '}
              <Link href={`mailto:${PARTNER_CONTACT_EMAIL}?subject=Partnership%20enquiry`}>
                {PARTNER_CONTACT_EMAIL}
              </Link>
              .
            </Typography>
          </Paper>

          <Alert severity="info">
            Already have credentials?{' '}
            <Link component={RouterLink} to="/login">
              Sign in to the partner portal
            </Link>
            . New integrators can{' '}
            <Link component={RouterLink} to="/register?type=partner">
              register as a partner
            </Link>{' '}
            or email{' '}
            <Link href={`mailto:${PARTNER_CONTACT_EMAIL}?subject=Partnership%20enquiry`}>
              {PARTNER_CONTACT_EMAIL}
            </Link>{' '}
            for onboarding assistance.
          </Alert>
        </Stack>
      </Container>
    </Box>
  );
};

export default PartnersPage;
