import React from 'react';
import { Box, Card, CardContent, List, ListItem, ListItemIcon, ListItemText, Typography } from '@mui/material';
import { CheckCircleOutline, RadioButtonUnchecked } from '@mui/icons-material';
import { getSignupGoalOption, type SignupGoalId } from '../../constants/signupGoals';

export interface PostRegistrationChecklistProps {
  companyName: string;
  pathway: 'msme' | 'enterprise';
  signupGoal?: SignupGoalId | null;
}

const MSME_DEFAULT_STEPS = [
  'Map GHG organizational & operational boundaries',
  'Configure production units and energy sources',
  'Upload utility bills for evidence-backed inventory',
  'Run your first carbon assessment',
];

const ENTERPRISE_DEFAULT_STEPS = [
  'Confirm facilities and Scope 3 materiality',
  'Complete evidence-backed compliance workflow',
  'Connect accounting data or upload documents',
  'Run enterprise carbon inventory',
];

export const PostRegistrationChecklist: React.FC<PostRegistrationChecklistProps> = ({
  companyName,
  pathway,
  signupGoal,
}) => {
  const goal = getSignupGoalOption(signupGoal ?? null);
  const steps = pathway === 'enterprise' ? ENTERPRISE_DEFAULT_STEPS : MSME_DEFAULT_STEPS;

  return (
    <Card variant="outlined" sx={{ maxWidth: 560, mx: 'auto', mb: 3, textAlign: 'left' }}>
      <CardContent>
        <Typography variant="subtitle1" sx={{ fontWeight: 700, mb: 0.5 }}>
          Your next steps for {companyName}
        </Typography>
        {goal && (
          <Typography variant="body2" color="text.secondary" sx={{ mb: 1.5 }}>
            Goal: <strong>{goal.label}</strong> — {goal.nextStepHint}
          </Typography>
        )}
        <List dense disablePadding>
          {steps.map((step, idx) => (
            <ListItem key={step} disablePadding sx={{ py: 0.25 }}>
              <ListItemIcon sx={{ minWidth: 32 }}>
                {idx === 0 ? (
                  <CheckCircleOutline color="primary" fontSize="small" />
                ) : (
                  <RadioButtonUnchecked color="disabled" fontSize="small" />
                )}
              </ListItemIcon>
              <ListItemText primary={step} primaryTypographyProps={{ variant: 'body2' }} />
            </ListItem>
          ))}
        </List>
        <Box sx={{ mt: 1 }}>
          <Typography variant="caption" color="text.secondary">
            Estimated time to first report: {pathway === 'enterprise' ? '2–4 hours' : '1–2 hours'} with documents ready.
          </Typography>
        </Box>
      </CardContent>
    </Card>
  );
};
