import React from 'react';
import { Alert, Box, Link, Typography } from '@mui/material';
import { Devices as DevicesIcon } from '@mui/icons-material';
import { PLATFORM_MOBILE_STRENGTHS, PLATFORM_ROLES_SUMMARY, PLATFORM_WEB_STRENGTHS } from '../constants/platformGuidance';

export interface PlatformGuidanceBannerProps {
  /** When true, emphasize mobile capture (shown on web dashboard). */
  variant?: 'web' | 'mobile';
  onDismiss?: () => void;
}

export const PlatformGuidanceBanner: React.FC<PlatformGuidanceBannerProps> = ({
  variant = 'web',
  onDismiss,
}) => {
  const strengths = variant === 'web' ? PLATFORM_MOBILE_STRENGTHS : PLATFORM_WEB_STRENGTHS;

  return (
    <Alert
      severity="info"
      icon={<DevicesIcon />}
      onClose={onDismiss}
      sx={{ mb: 2 }}
    >
      <Typography variant="body2" sx={{ fontWeight: 600, mb: 0.5 }}>
        {PLATFORM_ROLES_SUMMARY}
      </Typography>
      <Box component="ul" sx={{ m: 0, pl: 2.5 }}>
        {strengths.map((item) => (
          <Typography key={item} component="li" variant="caption" color="text.secondary">
            {item}
          </Typography>
        ))}
      </Box>
      {variant === 'mobile' ? (
        <Typography variant="caption" sx={{ mt: 1, display: 'block' }}>
          Open the web app at{' '}
          <Link href="https://carbonintelligence.sustainow.in" target="_blank" rel="noopener noreferrer">
            carbonintelligence.sustainow.in
          </Link>
        </Typography>
      ) : null}
    </Alert>
  );
};

export default PlatformGuidanceBanner;
