import React, { useEffect, useState } from 'react';
import {
  Alert,
  Box,
  Chip,
  Container,
  Paper,
  Stack,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Typography,
} from '@mui/material';
import { buildApiUrl } from '../../config/apiConfig';
import { PARTNER_SUPPORT_EMAIL } from '../../constants/partnerProgram';

interface IntegrationCatalog {
  version: string;
  authentication: {
    type: string;
    headerOptions: string[];
    keyPrefix: string;
    note: string;
  };
  scopes: { id: string; description: string }[];
  endpoints: { method: string; path: string; access: string; scopes?: string[] }[];
  supportEmail: string;
}

const PUBLIC_ENDPOINT_DETAILS: Record<
  string,
  { description: string; queryParams?: string; responseNotes?: string }
> = {
  'GET /api/v1/public/integration-catalog': {
    description:
      'Returns the live integration catalog including authentication guidance, scopes, endpoint list, and indicative partnership pricing.',
    responseNotes: 'No authentication required. JSON body includes version, scopes, endpoints, and partnershipPricing.',
  },
  'GET /api/v1/public/openapi.json': {
    description: 'Machine-readable OpenAPI 3.0 specification for public and partner REST endpoints.',
    responseNotes: 'No authentication required. Suitable for code generation and API client tooling.',
  },
  'GET /api/v1/partners/me': {
    description: 'Returns the partner application profile linked to the authenticated API key.',
    responseNotes: 'Includes organization name, scopes, billing plan, usage limits, and masked key prefix.',
  },
  'GET /api/v1/partners/usage': {
    description: 'Current usage, quotas, success rates, and indicative billing for the authenticated API key.',
    queryParams: 'days (7–90, default 30)',
  },
  'GET /api/v1/partners/msmes': {
    description: 'Paginated list of MSME company summaries accessible to your partner scopes.',
    queryParams: 'page, limit, status, search',
    responseNotes: 'Requires msme:read scope. Excludes passwords and document binaries.',
  },
  'GET /api/v1/partners/msmes/:msmeId/carbon-summary': {
    description: 'Latest carbon assessment summary for a specific MSME.',
    responseNotes: 'Requires carbon:read scope.',
  },
  'GET /api/v1/partners/msmes/:msmeId/reports/overview': {
    description: 'Reporting readiness metadata and disclosure pack status for an MSME.',
    responseNotes: 'Requires reports:read scope.',
  },
  'GET /api/v1/partners/msmes/:msmeId/transactions/summary': {
    description: 'Aggregated transaction metrics without raw line-item export.',
    responseNotes: 'Requires transactions:summary scope.',
  },
  'PATCH /api/v1/partners/webhook': {
    description: 'Configure an HTTPS webhook URL for outbound partner events.',
    responseNotes: 'Requires webhooks:manage scope. Body: { webhookUrl }.',
  },
};

const PARTNER_PORTAL_ENDPOINTS = [
  {
    method: 'POST',
    path: '/api/auth/login',
    access: 'Public',
    description: 'Unified sign-in for partner portal users (role: partner). Returns JWT and linked partner profile.',
  },
  {
    method: 'GET',
    path: '/api/partner-account/me',
    access: 'Partner JWT',
    description: 'Current partner user and linked application metadata.',
  },
  {
    method: 'GET',
    path: '/api/partner-account/dashboard',
    access: 'Partner JWT',
    description: 'Usage, billing estimates, endpoint statistics, and daily call series.',
  },
  {
    method: 'GET',
    path: '/api/partner-account/usage',
    access: 'Partner JWT',
    description: 'Detailed usage breakdown for the linked partner application.',
  },
  {
    method: 'GET',
    path: '/api/partner-account/billing',
    access: 'Partner JWT',
    description: 'Indicative billing based on plan, contract fee, and overage rates.',
  },
  {
    method: 'GET',
    path: '/api/partner-account/statistics',
    access: 'Partner JWT',
    description: 'Success rates, latency percentiles, and top endpoints.',
  },
];

const PartnerApiDocumentationPage: React.FC = () => {
  const [catalog, setCatalog] = useState<IntegrationCatalog | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetch(buildApiUrl('/v1/public/integration-catalog'))
      .then(async (res) => {
        const body = await res.json();
        if (!res.ok || !body.success) {
          throw new Error(body.message || 'Failed to load integration catalog');
        }
        setCatalog(body.data);
      })
      .catch((err: Error) => setError(err.message));
  }, []);

  const supportEmail = catalog?.supportEmail || PARTNER_SUPPORT_EMAIL;
  const apiBase = buildApiUrl('').replace(/\/api$/, '');

  return (
    <Box sx={{ minHeight: '100vh', bgcolor: 'background.default', py: 4 }}>
      <Container maxWidth="lg">
        <Stack spacing={3}>
          <Box>
            <Typography variant="h4" component="h1" gutterBottom>
              Public API documentation
            </Typography>
            <Typography variant="body1" color="text.secondary" sx={{ maxWidth: 900 }}>
              REST endpoints for banks, auditors, verification agencies, and integration partners.
              MSME-facing JWT APIs remain unchanged; machine-to-machine access uses scoped partner API keys.
            </Typography>
          </Box>

          {error && (
            <Alert severity="warning">
              Live catalog unavailable ({error}). Reference documentation below is still valid; retry after the API
              is reachable.
            </Alert>
          )}

          <Paper sx={{ p: 3 }}>
            <Typography variant="h5" gutterBottom>
              Authentication
            </Typography>
            <Typography variant="body2" color="text.secondary" paragraph>
              Send your partner API key using either header format. Keys use the{' '}
              <code>{catalog?.authentication.keyPrefix || 'ci_live_'}</code> prefix and are issued when you register
              as a partner or when an administrator provisions your application.
            </Typography>
            <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap sx={{ mb: 2 }}>
              {(catalog?.authentication.headerOptions || ['X-API-Key', 'Authorization: Bearer <api_key>']).map(
                (header) => (
                  <Chip key={header} label={header} size="small" variant="outlined" />
                ),
              )}
            </Stack>
            <Typography variant="body2" color="text.secondary">
              Invalid or revoked keys return HTTP 401. Partner portal dashboards use JWT from{' '}
              <code>POST /api/auth/login</code> with your partner account credentials.
            </Typography>
          </Paper>

          <Paper sx={{ p: 3 }}>
            <Typography variant="h5" gutterBottom>
              Scopes
            </Typography>
            <TableContainer>
              <Table size="small">
                <TableHead>
                  <TableRow>
                    <TableCell>Scope</TableCell>
                    <TableCell>Capability</TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {(catalog?.scopes || [
                    { id: 'msme:read', description: 'List and read MSME company summaries' },
                    { id: 'carbon:read', description: 'Read carbon assessment summaries' },
                    { id: 'reports:read', description: 'Read reporting readiness metadata' },
                    {
                      id: 'transactions:summary',
                      description: 'Read aggregated transaction metrics (no raw line items)',
                    },
                    { id: 'webhooks:manage', description: 'Configure outbound webhook URL on the partner application' },
                  ]).map((scope) => (
                    <TableRow key={scope.id}>
                      <TableCell>
                        <code>{scope.id}</code>
                      </TableCell>
                      <TableCell>{scope.description}</TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </TableContainer>
          </Paper>

          <Paper sx={{ p: 3 }}>
            <Typography variant="h5" gutterBottom>
              Public &amp; partner REST endpoints
            </Typography>
            <Typography variant="body2" color="text.secondary" paragraph>
              Base URL: <code>{apiBase}/api</code>
              {catalog ? ` · Catalog version ${catalog.version}` : ''}
            </Typography>
            <TableContainer>
              <Table size="small">
                <TableHead>
                  <TableRow>
                    <TableCell>Method</TableCell>
                    <TableCell>Path</TableCell>
                    <TableCell>Access</TableCell>
                    <TableCell>Scopes</TableCell>
                    <TableCell>Details</TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {(catalog?.endpoints || [
                    { method: 'GET', path: '/api/v1/public/integration-catalog', access: 'public' },
                    { method: 'GET', path: '/api/v1/public/openapi.json', access: 'public' },
                    { method: 'GET', path: '/api/v1/partners/me', access: 'partner', scopes: [] },
                    { method: 'GET', path: '/api/v1/partners/usage', access: 'partner', scopes: [] },
                    { method: 'GET', path: '/api/v1/partners/msmes', access: 'partner', scopes: ['msme:read'] },
                    {
                      method: 'GET',
                      path: '/api/v1/partners/msmes/:msmeId/carbon-summary',
                      access: 'partner',
                      scopes: ['carbon:read'],
                    },
                    {
                      method: 'GET',
                      path: '/api/v1/partners/msmes/:msmeId/reports/overview',
                      access: 'partner',
                      scopes: ['reports:read'],
                    },
                    {
                      method: 'GET',
                      path: '/api/v1/partners/msmes/:msmeId/transactions/summary',
                      access: 'partner',
                      scopes: ['transactions:summary'],
                    },
                    {
                      method: 'PATCH',
                      path: '/api/v1/partners/webhook',
                      access: 'partner',
                      scopes: ['webhooks:manage'],
                    },
                  ]).map((endpoint) => {
                    const detailKey = `${endpoint.method} ${endpoint.path}`;
                    const detail = PUBLIC_ENDPOINT_DETAILS[detailKey];
                    return (
                      <TableRow key={detailKey}>
                        <TableCell>{endpoint.method}</TableCell>
                        <TableCell>
                          <code>{endpoint.path}</code>
                        </TableCell>
                        <TableCell>{endpoint.access}</TableCell>
                        <TableCell>
                          {endpoint.scopes?.length ? endpoint.scopes.join(', ') : '—'}
                        </TableCell>
                        <TableCell>
                          <Typography variant="body2">{detail?.description || '—'}</Typography>
                          {detail?.queryParams && (
                            <Typography variant="caption" color="text.secondary" display="block">
                              Query: {detail.queryParams}
                            </Typography>
                          )}
                          {detail?.responseNotes && (
                            <Typography variant="caption" color="text.secondary" display="block">
                              {detail.responseNotes}
                            </Typography>
                          )}
                        </TableCell>
                      </TableRow>
                    );
                  })}
                </TableBody>
              </Table>
            </TableContainer>
          </Paper>

          <Paper sx={{ p: 3 }}>
            <Typography variant="h5" gutterBottom>
              Partner portal account API
            </Typography>
            <Typography variant="body2" color="text.secondary" paragraph>
              After registering as a partner, sign in at <code>/login</code> to access usage dashboards at{' '}
              <code>/partner/dashboard</code>. These endpoints require a partner JWT.
            </Typography>
            <TableContainer>
              <Table size="small">
                <TableHead>
                  <TableRow>
                    <TableCell>Method</TableCell>
                    <TableCell>Path</TableCell>
                    <TableCell>Access</TableCell>
                    <TableCell>Description</TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {PARTNER_PORTAL_ENDPOINTS.map((endpoint) => (
                    <TableRow key={`${endpoint.method}-${endpoint.path}`}>
                      <TableCell>{endpoint.method}</TableCell>
                      <TableCell>
                        <code>{endpoint.path}</code>
                      </TableCell>
                      <TableCell>{endpoint.access}</TableCell>
                      <TableCell>{endpoint.description}</TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </TableContainer>
          </Paper>

          <Paper sx={{ p: 3 }}>
            <Typography variant="h5" gutterBottom>
              Example request
            </Typography>
            <Box
              component="pre"
              sx={{
                p: 2,
                bgcolor: 'action.hover',
                borderRadius: 1,
                overflow: 'auto',
                fontSize: '0.85rem',
                m: 0,
              }}
            >
              {`curl -s -H "X-API-Key: $PARTNER_API_KEY" \\
  "${apiBase}/api/v1/partners/msmes?limit=5"`}
            </Box>
            <Typography variant="body2" color="text.secondary" sx={{ mt: 2 }}>
              Partner responses exclude passwords, full transaction line items, and document binaries. Rotate keys
              through your administrator when staff change roles. For technical support, email{' '}
              <a href={`mailto:${supportEmail}`}>{supportEmail}</a>.
            </Typography>
          </Paper>
        </Stack>
      </Container>
    </Box>
  );
};

export default PartnerApiDocumentationPage;
